// saxpy trio: streaming update, reversed gather, dot-product reduction.
// plus a branch-heavy helper so the CFG view shows two functions.
fn clampidx(i: i64, n: i64) -> i64 {
    if i < 0 {
        return 0;
    }
    if i >= n {
        return n - 1;
    }
    return i;
}

fn main() {
    let n = 33554432;
    let x: [f64] = zeros(n);
    let y: [f64] = zeros(n);

    // loop #0 - elementwise stream: iterations are independent
    for i in 0..n {
        y[i] = 2.5 * x[i] + y[i];
    }

    // loop #1 - reversed gather: carries a RAW dependence
    let h = n / 2;
    for j in 0..h {
        y[j] = y[n - j - 1];
    }

    // loop #2 - dot product: floating-point +-reduction
    let dot = 0.0;
    for k in 0..n {
        dot = dot + x[k] * y[k];
    }
    print(dot);
}
